const body = $json || {};
let content = "";
try { content = body.choices[0].message.content || ""; } catch (e) { content = ""; }
let parsed = {};
let ok = false;
if (content) {
  try {
    let c = String(content).trim();
    const m = c.match(/\{[\s\S]*\}/);
    if (m) { c = m[0]; }
    parsed = JSON.parse(c);
    ok = true;
  } catch (e) { ok = false; }
}
return { json: { parsed_ok: ok, model_content: content, approved: ok ? (parsed.approved === true) : null, score: ok ? parsed.score : null, note: ok ? parsed.note : null } };
